const svg=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`,names=Object.keys(icons);
let local=false,token='',active='Dashboard',state=null,players=[],currentY=0,frameId=0,recordFiles=[],polling=false,lastTraffic=null,points=[];
