function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function move(){cancelAnimationFrame(frameId);const from=currentY,to=document.querySelector(`[data-page="${active}"]`).offsetTop,start=performance.now();function frame(t){const p=motion?Math.min(1,(t-start)/850):1,e=p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;currentY=from+(to-from)*e;$('#cutout').style.transform=`translateY(${currentY}px)`;if(p<1)frameId=requestAnimationFrame(frame)}frameId=requestAnimationFrame(frame)}
function isPaused(c){return c.enabled===false||(c.kind==='sample'&&!state.server.sampleRunning)}
async function updateCamera(endpoint,body,method){state=await request(endpoint,body,method);render()}
function duration(ms){const s=Math.floor(Math.max(0,ms)/1000);return `${s>=3600?String(Math.floor(s/3600)).padStart(2,'0')+':':''}${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function recordingLabel(c){const elapsed=(c.recordElapsedMs||0)+(c.recordStartedAt?Math.max(0,Date.now()-c.recordStartedAt):0);return (c.record||c.recordSessionOpen)?`${c.recordStartedAt?'● Recording':'Recording paused'} · ${duration(elapsed)}`:c.lastRecordingMs?`Last recording · ${duration(c.lastRecordingMs)}`:c.status}
function updateRecordingTimers(){document.querySelectorAll('[data-record-timer]').forEach(el=>{const c=state?.cameras.find(c=>c.id===el.dataset.recordTimer);if(c)el.textContent=recordingLabel(c)})}
function serverControls(){return `<div class="server-controls"><span data-server-status>${state.server.running?'Server running':'Server stopped'}</span><button class="secondary" data-action="server/start" ${state.server.running?'disabled':''}>Start server</button><button class="secondary" data-action="server/stop" ${state.server.running?'':'disabled'}>Stop server</button></div>`}
function syncServerControls(){document.querySelectorAll('[data-action="server/start"]').forEach(b=>b.disabled=state.server.running);document.querySelectorAll('[data-action="server/stop"]').forEach(b=>b.disabled=!state.server.running);document.querySelectorAll('[data-server-status]').forEach(el=>el.textContent=state.server.running?'Server running':'Server stopped');document.querySelectorAll('[data-action^="sample/"]').forEach(b=>{b.dataset.action=`sample/${state.server.sampleRunning?'stop':'start'}`;b.textContent=`${state.server.sampleRunning?'Stop':'Start'} sample stream`});if($('#serverVersion'))$('#serverVersion').textContent=state.server.version||'Stopped';updateRecordingTimers()}
let managerStopped=false;
const confirmation=document.createElement('dialog');confirmation.setAttribute('aria-labelledby','confirmTitle');confirmation.innerHTML='<h2 id="confirmTitle">Confirm action</h2><p id="confirmMessage"></p><div class="dialog-actions"><button class="secondary" id="confirmCancel">Cancel</button><button class="primary" id="confirmContinue">Continue</button></div>';document.body.append(confirmation);
function confirmAction(message){return new Promise(resolve=>{confirmation.querySelector('#confirmMessage').textContent=message;confirmation.returnValue='cancel';confirmation.querySelector('#confirmCancel').onclick=()=>confirmation.close('cancel');confirmation.querySelector('#confirmContinue').onclick=()=>confirmation.close('continue');confirmation.addEventListener('close',()=>resolve(confirmation.returnValue==='continue'),{once:true});confirmation.showModal()})}
