function illustration(){return `<svg viewBox="0 0 280 200" aria-label="Illustrated placeholder 3D printer"><ellipse cx="140" cy="182" rx="110" ry="11" fill="#060d18"/><path d="M58 165V24h164v141M73 161V38h134v123" fill="none" stroke="#47617b" stroke-width="9"/><path d="M55 82h169" stroke="#6b839a" stroke-width="7"/><path d="m52 163 95-24 88 29-99 27z" fill="#223b57" stroke="#6281a0"/><path d="m111 153 29-12 30 10v23l-28 9-31-10z" fill="#5e8add"/><rect x="128" y="67" width="27" height="30" rx="5" fill="#8ba5bc"/><circle cx="141" cy="81" r="8" fill="#23344a"/></svg>`}
function card(c){const live=local&&c.status==='Live';return `<article class="camera"><div class="camera-visual">${live?`<video data-live="${esc(c.path)}" autoplay muted playsinline controls aria-label="${esc(c.name)} live video"></video>`:local?`<div class="feed-empty">${svg('Cameras')}<strong>${c.status==='Paused'?'Camera paused':'Waiting for video'}</strong><span>${c.kind==='sample'?'Start the sample stream to test playback.':'Check the camera address, account, power, and Wi-Fi.'}</span></div>`:illustration()}<span class="live"><i style="background:${live?'#61dcb5':'#91a4bf'}"></i>${local?esc(c.status.toUpperCase()):'DESIGN PREVIEW'}</span>${live?`<button class="preview-btn" data-view="${c.id}">Expand ↗</button>`:''}</div><div class="camera-info"><div><h3>${esc(c.name)}</h3><p>/${esc(c.path)} · ${c.kind==='sample'?'Generated test video':local?(c.stream==='stream2'?'Low bandwidth':'Main stream'):'1080p placeholder'}</p></div><span class="recording-timer" data-record-timer="${c.id}" aria-live="off">${esc(recordingLabel(c))}</span></div><p class="viewer-count" data-viewers="${c.id}">${local?`${c.publicViewers||0} watching on website`:"Website viewers available in the local app"}</p><div class="camera-actions">${local?`<button class="secondary" data-record="${c.id}">${c.record?'■ Stop recording':'● Record'}</button>${c.kind!=='sample'?`<button class="secondary" data-edit="${c.id}">Edit</button>`:''}<button class="secondary" data-enabled="${c.id}">${isPaused(c)?'Resume':'Pause'}</button><button class="text-button" data-remove="${c.id}">Remove</button>`:'<button class="secondary" data-setup>Connect in local app</button>'}</div></article>`}
function empty(){return `<div class="panel welcome"><span class="eyebrow">LET’S GET CONNECTED</span><h2>Your studio starts here.</h2><p>No cameras yet? Test real playback and recording with the included sample stream.</p><div class="page-actions"><button class="primary" data-action="sample/start">▶ Start sample stream</button><button class="secondary" data-add>＋ Add your Tapo camera</button></div></div>`}
function activity(){return state.activity.slice(0,12).map(x=>`<div class="activity"><i></i><div>${esc(x.message)}<small>${new Date(x.time).toLocaleString()}</small></div></div>`).join('')||'<p class="hint">Activity will appear here.</p>'}
function chart(){return `<svg class="chart" viewBox="0 0 600 120" preserveAspectRatio="none" role="img" aria-label="${local?'Measured traffic history':'Illustrative demo traffic'}: incoming blue with fading fill, outgoing orange line"><defs><linearGradient id="incomingFade" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" stop-color="#6aaaff" stop-opacity=".42"/><stop offset="55%" stop-color="#6aaaff" stop-opacity=".18"/><stop offset="100%" stop-color="#6aaaff" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 20h600M0 60h600M0 100h600"/><path id="inArea" fill="url(#incomingFade)" stroke="none"/><path id="inLine" class="chart-line"/><path id="outLine" class="chart-line second"/></svg><div class="chart-labels"><span>Last 2 minutes</span><span id="trafficLabel">${local?'Collecting traffic…':'Illustrative sample data'}</span><span>Now</span></div>`}
function plot(){if(!$('#inLine'))return;const v=local?points:Array.from({length:30},(_,i)=>({incoming:2+Math.sin(i*.7),outgoing:.8+.4*Math.sin(i*.6)})),max=Math.max(1,...v.map(x=>Math.max(x.incoming,x.outgoing)));for(const [id,key] of [['#inLine','incoming'],['#outLine','outgoing']]){const p=v.map((x,i)=>[i*600/Math.max(1,v.length-1),110-x[key]/max*95]);let d=p.length?`M${p[0][0]} ${p[0][1]}`:'';for(let i=1;i<p.length;i++){const a=p[i-2]||p[i-1],b=p[i-1],c=p[i],e=p[i+1]||c;d+=` C${b[0]+(c[0]-a[0])/6} ${b[1]+(c[1]-a[1])/6} ${c[0]-(e[0]-b[0])/6} ${c[1]-(e[1]-b[1])/6} ${c[0]} ${c[1]}`}$(id).setAttribute('d',d);if(key==='incoming')$('#inArea').setAttribute('d',p.length>1?`${d} L${p.at(-1)[0]} 110 L${p[0][0]} 110 Z`:'')}if(local&&v.length)$('#trafficLabel').textContent=`In ${v.at(-1).incoming.toFixed(2)} / Out ${v.at(-1).outgoing.toFixed(2)} Mbps`}
function uptime(){let s=Math.floor((Date.now()-(state.server.startedAt||Date.now()))/1000);return `${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`}
function render(){if(managerStopped)return showManagerStopped();destroyPlayers();header();document.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});let html='',cams=state.cameras,add='<button class="primary" data-add>＋ Add camera</button>';
if(active==='Dashboard'){const stats=[['Cameras live',local?cams.filter(c=>c.status==='Live').length:2,local?`${cams.length} configured cameras`:'Illustrative demo count','Cameras'],['Active streams',local?state.paths.filter(p=>p.ready).length:2,local?'Reported by MediaMTX':'Illustrative demo count','Streams'],['Incoming bandwidth',local?'0.00':'4.8',local?'Mbps · measured live':'Mbps · illustrative','Activity'],['Server uptime',local&&state.server.running?uptime():'—',local?'Managed locally':'Local app required','Settings']];html=title('Dashboard','A clear view of your studio. Everything in one place.',add)+`<div class="stats">${stats.map((s,i)=>`<div class="stat">${svg(s[3])}<label>${s[0]}</label><strong ${i===2?'id="bandwidth"':i===3?'id="uptime"':''}>${s[1]}</strong><small>${s[2]}</small></div>`).join('')}</div>`+(cams.length?`<div class="section-heading"><h2>Camera overview</h2><span>${cams.length} ${local?'configured':'demo'} cameras</span></div><div class="camera-grid">${cams.map(card).join('')}</div>`:empty())+`<div class="lower"><section class="panel"><div class="section-heading"><h2>Network activity</h2><span>${local?'Measured':'Demo'} · <span class="traffic-in">━ Incoming</span> <span class="traffic-out">━ Outgoing</span></span></div>${chart()}</section><section class="panel"><div class="section-heading"><h2>Recent activity</h2></div>${activity()}</section></div>`}
if(active==='Help')html=title('Help & FAQ','Quick answers for cameras, recordings and website viewing.')+faqPage();
if(active==='Cameras')html=title('Cameras','Your studio, from every angle.',add)+(cams.length?`<div class="camera-grid">${cams.map(card).join('')}</div>`:empty());
if(active==='Streams')html=title('Streams','Live paths, connection state, and recording controls.',local?`<button class="secondary" data-action="sample/${state.server.sampleRunning?'stop':'start'}">${state.server.sampleRunning?'Stop':'Start'} sample stream</button>`:'')+`<section class="panel table-wrap"><table><thead><tr><th>STREAM</th><th>STATUS</th><th>TYPE</th><th>RECORDING</th></tr></thead><tbody>${cams.map(c=>`<tr><td>${esc(c.name)}<br><span class="hint">/${esc(c.path)}</span></td><td>${esc(c.status)}</td><td>${c.kind==='sample'?'Sample video':'Tapo / RTSP'}</td><td>${local?`<button data-record="${c.id}">${c.record?'Stop recording':'Start recording'}</button>`:'Preview only'}</td></tr>`).join('')||'<tr><td colspan="4">No streams configured yet.</td></tr>'}</tbody></table></section><p class="hint">${local?'Live video is delivered through the local MediaMTX server. Allow a few seconds for playback to buffer.':'This hosted preview is not connected to your cameras. Run the Windows package for real streams.'}</p>`;
if(active==='Recordings')html=title('Recordings',local?'Video saved on this computer. Stop recording to finalize the current file.':'Your saved videos will appear here in the local app.','<button class="secondary" data-action="recordings">↻ Refresh recordings</button>')+`<section class="panel" id="recordingList">${local?'Loading recordings…':'<div class="empty">No live recordings in this design preview.<br><br><button class="secondary" data-setup>About the Windows package</button></div>'}</section>`;
if(active==='Activity')html=title('Activity','Connection changes and actions from your workspace.')+`<section class="panel">${activity()}</section>`;
if(active==='About')html=title('About','The people and software behind your camera workspace.')+`<div class="about-stack"><section class="panel about-maker"><img class="about-logo" src="assets/mindvision-graphics-logo.png" width="1024" height="304" alt="MindVision Graphics"><p class="eyebrow">CREATED BY MINDVISION GRAPHICS</p><h2>MediaMTX Manager</h2><p>A clear view of your studio. Built to bring camera viewing, recording and public printing streams into one simple workspace.</p><a class="primary about-site" href="https://mindvisiongraphics.com/" target="_blank" rel="noopener noreferrer">Visit MindVision Graphics ↗</a></section><section class="panel"><h2 class="small-heading">About this release</h2><dl class="about-details"><div><dt>Application</dt><dd>MediaMTX Manager</dd></div><div><dt>Created by</dt><dd>MindVision Graphics</dd></div><div><dt>Build</dt><dd>2026.10.22</dd></div><div><dt>Edition</dt><dd>${local?(state.platform==='darwin'?'macOS local manager':'Windows local manager'):'Design preview'}</dd></div><div><dt>MediaMTX engine</dt><dd>${esc(local?(state.server.version||'Server stopped'):'Available in the Windows app')}</dd></div></dl></section><section class="panel"><h2 class="small-heading">Powered by open-source software</h2><p class="hint">This interface is created by MindVision Graphics. Video routing is powered by MediaMTX, with FFmpeg, Node.js and hls.js supporting video processing, the local app and browser playback.</p><p class="hint">MediaMTX Manager is an independent application and is not affiliated with MediaMTX, TP-Link or Tapo.</p><a class="about-link" href="about-notices.txt" target="_blank" rel="noopener">View included software credits and license information ↗</a></section></div>`;
if(active==='Settings')html=title('Settings','Your workspace. Your local server.')+`<div class="settings-stack"><section class="panel"><div class="section-heading"><h2>MediaMTX server</h2><span id="serverVersion">${local?(state.server.version||'Stopped'):'Local app required'}</span></div><p class="hint">${local?'The server runs on this computer and is managed by this app.':'Use the Windows package to run and manage your server.'}</p>${state.server.error?`<p class="error-text" role="alert">${esc(state.server.error)}</p>`:''}<div class="page-actions">${local?`${serverControls()}<button class="secondary" data-action="sample/${state.server.sampleRunning?'stop':'start'}">${state.server.sampleRunning?'Stop':'Start'} sample stream</button><button class="text-button" data-action="shutdown">Quit manager</button>`:'<button class="primary" data-setup>Windows setup</button>'}</div><p class="hint">${local?'Stop server pauses streaming. Quit manager stops the camera manager; the local launcher keeps this page available so Start manager can reconnect this same tab.':'No camera credentials are collected by this hosted preview.'}</p></section><form id="settingsForm" class="panel settings"><h2 class="small-heading">Workspace preferences</h2><label>Workspace name<input name="workspace" maxlength="60" required value="${esc(state.workspace)}"></label><label>Animate connected-curve navigation<input name="motion" type="checkbox" ${motion?'checked':''}></label><p class="hint">${local?'Camera passwords are protected with Windows encryption. Recordings stay in data/recordings.':'Preview preferences are saved in this browser.'}</p><button class="primary">Save preferences</button></form><section class="panel"><h2 class="small-heading">Moving to your camera computer</h2><p class="hint">Extract a fresh copy of the Windows package there and open Start Manager.vbs. Add cameras using their IP addresses and Camera Accounts. Saved passwords are tied to the Windows account that created them.</p><p class="hint">This version opens on the computer running the manager. Access from other devices will need a separate, authenticated network-access option.</p></section></div>`;
const viewerSummary='<section class="panel viewer-summary"><strong id="websiteViewerTotal">'+(state.viewerCount||0)+'</strong> watching on website<p class="hint">Estimated active viewing sessions · updates automatically. See Help for how counting works.</p></section>';if(local&&['Dashboard','Cameras'].includes(active)){const heading=title(active,active==='Dashboard'?'A clear view of your studio. Everything in one place.':'Your studio, from every angle.',add);html=html.replace(heading,heading+viewerSummary)}$('#page').innerHTML=html;plot();attachLive();if(active==='Recordings'&&local){loadRecordings();loadAutomation()}if(active==='Settings'&&local){loadSharing();loadBackup()}if(active==='Streams'&&local)loadForwarding()}
let forwardingPolling=false;
async function refreshForwarding(){
  const list=$('#forwardingList');if(!list||forwardingPolling)return;forwardingPolling=true;
  try{const r=await fetch('/api/forwarding',{cache:'no-store'});if(!r.ok)throw Error('Apply the stream forwarding update to use these controls.');const {items}=await r.json();if(!list.isConnected)return;
    list.innerHTML=items.length?items.map(d=>`<article class="forward-card"><h3>${esc(d.name)}</h3><p class="hint">${esc(state.cameras.find(c=>c.id===d.cameraId)?.name||'Camera unavailable')} → ${esc(d.destination)}</p><p><strong>${esc(d.status)}</strong> <span class="hint">· ${(d.outboundBytes/1048576).toFixed(2)} MB sent this session</span></p>${d.error?`<p class="error-text" role="status">${esc(d.error)}</p>`:''}${!d.hasEndpoint?'<p class="hint">Stream key missing. Remove and add this destination again with its key.</p>':''}<div class="page-actions"><button class="primary" data-forward-action="start" data-forward-id="${d.id}" ${d.enabled||!d.hasEndpoint?'disabled':''}>Start forwarding</button><button class="secondary" data-forward-action="stop" data-forward-id="${d.id}" ${d.enabled?'':'disabled'}>Stop forwarding</button><button class="text-button" data-forward-action="remove" data-forward-id="${d.id}">Remove destination</button></div></article>`).join(''):'<p class="hint">No forwarding destinations yet. Saving a destination does not send video.</p>';
  }catch(error){if(list.isConnected)list.textContent=error.message}finally{forwardingPolling=false}
}
function loadForwarding(){
  const panel=document.createElement('section');panel.className='panel forwarding-panel';panel.id='forwardingPanel';$('#page').append(panel);
  panel.innerHTML=`<h2>Stream forwarding <span class="forward-badge">Experimental</span></h2><p class="hint">Send a camera to another RTMP/RTMPS streaming server. Local forwarding is tested; each outside service still needs its own test. Video is sent with a silent audio track for compatibility. This does not change your recordings or website viewer.</p><form id="forwardingForm" class="backup-form"><div class="form-grid"><label>Destination name<input name="name" required maxlength="60" placeholder="My streaming destination"></label><label>Camera<select name="cameraId" required>${state.cameras.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.status)}</option>`).join('')}</select></label></div><label>Streaming server URL<input name="server" type="url" required maxlength="2000" placeholder="rtmps://stream.example.com/app" autocomplete="off"></label><label>Stream key<input name="streamKey" type="password" required maxlength="1024" autocomplete="new-password"></label><p class="hint">Copy the server URL and stream key from your destination service. Keys are saved with Windows encryption and are never shown in the list. Saving does not start a broadcast. To change an address or key, remove that destination and add it again.</p><button class="primary" ${state.cameras.length?'':'disabled'}>Save destination</button><p class="hint" id="forwardingResult" role="status"></p></form><div id="forwardingList">Loading destinations…</div><p class="hint">Forwarding requires a live H.264 camera. It stays stopped after a camera pause, server restart or manager restart until you press Start forwarding again.</p>`;
  $('#forwardingForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await request('forwarding',Object.fromEntries(new FormData(f)));f.reset();$('#forwardingResult').textContent='Destination saved. Press Start forwarding when you are ready to send video.';await refreshForwarding()}catch(error){$('#forwardingResult').textContent=error.message}finally{b.disabled=false}};
  refreshForwarding();
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-forward-action]');if(!b)return;const a=b.dataset.forwardAction,id=b.dataset.forwardId;
  if(a==='start'&&!await confirmAction('Start sending this camera to the saved streaming destination? People may be able to watch it through that service.'))return;
  if(a==='remove'&&!await confirmAction('Remove this forwarding destination? You will need its server address and stream key to add it again.'))return;
  b.disabled=true;try{await request(`forwarding/${id}/${a}`);await refreshForwarding()}catch(error){toast(error.message);b.disabled=false}
});
setInterval(()=>{if(local&&active==='Streams'&&!managerStopped)refreshForwarding()},3000);
async function loadBackup(){
  const stack=$('.settings-stack');if(!stack)return;const panel=document.createElement('section');panel.id='backupPanel';panel.className='panel';stack.insertBefore(panel,stack.lastElementChild);
  panel.innerHTML=`<h2 class="small-heading">Backup and restore</h2><p class="hint">Save cameras, schedules, storage limits and website sharing settings in a passphrase-protected file. Video recordings are separate and are not included.</p><form id="backupExportForm" class="backup-form"><h3>Create a backup</h3><label>Backup passphrase<input name="passphrase" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>Repeat passphrase<input name="repeat" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label class="inline-check"><input type="checkbox" name="includePasswords" checked> Include camera passwords and stream keys inside the encrypted backup</label><p class="hint">Use at least 12 characters and keep the passphrase somewhere safe. It cannot be recovered if forgotten. With credentials included, the file can move your setup to another computer.</p><button class="primary">Download encrypted backup</button><p class="hint" id="backupExportResult" role="status"></p></form><form id="backupRestoreForm" class="backup-form"><h3>Restore from a backup</h3><label>Backup file<input name="backupFile" type="file" accept=".json,.mtxbackup" required></label><label>Backup passphrase<input name="passphrase" type="password" autocomplete="off" minlength="12" maxlength="256" required></label><button class="secondary">Preview backup</button><p class="hint" id="backupRestoreResult" role="status"></p></form><div id="previousSetup" class="hint"></div><div id="backupPreview" aria-live="polite"></div>`;
  $('#backupExportForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),result=$('#backupExportResult');b.disabled=true;try{if(f.elements.passphrase.value!==f.elements.repeat.value)throw Error('The passphrases do not match.');const backup=await request('backup/export',{passphrase:f.elements.passphrase.value,includePasswords:f.elements.includePasswords.checked});const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MediaMTX-Manager-'+new Date().toLocaleDateString('en-CA')+'.mtxbackup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);f.reset();result.textContent='Encrypted backup download requested. Keep the file and its passphrase safe.'}catch(error){result.textContent=error.message}finally{b.disabled=false}};
  function showPreview(p){
    const area=$('#backupPreview');area.innerHTML=`<section class="backup-review"><h3>Review restore</h3><p><strong>${esc(p.workspace)}</strong> · Backup created ${esc(new Date(p.createdAt).toLocaleString())}</p><p class="hint">This replaces ${p.currentCameras.length} current camera(s) with ${p.cameras.length} camera(s) from the backup. Current recordings and stream forwarding will stop. Saved video files stay on this computer.</p><ul>${p.cameras.map(c=>`<li>${esc(c.name)}${c.needsPassword?' — re-enter its camera password after restoring':''}</li>`).join('')||'<li>No cameras in this backup.</li>'}</ul><details><summary>Current cameras being replaced</summary><ul>${p.currentCameras.map(name=>`<li>${esc(name)}</li>`).join('')||'<li>None</li>'}</ul></details><p class="hint">Cameras will arrive paused. Schedules, public sharing and automatic cleanup will be off until you review and enable them. A local restore point preserves your previous setup.</p><p class="hint">Schedule times will follow this computer’s time zone. Backup time zone: ${esc(p.timezone)}.</p><div class="page-actions"><button type="button" class="secondary" id="cancelRestore">Cancel</button><button type="button" class="primary" id="applyRestore">Restore these settings</button></div><p class="hint" id="applyRestoreResult" role="status"></p></section>`;
    const forwardingInfo=document.createElement('p');forwardingInfo.className='hint';forwardingInfo.textContent=`${p.forwardings?.length||0} forwarding destination(s) will be restored stopped. ${(p.forwardings||[]).filter(d=>d.needsKey).length} need their stream keys re-entered by removing and adding the destination again.`;area.querySelector('.page-actions').before(forwardingInfo);
    $('#cancelRestore').onclick=async()=>{await request('backup/cancel',{id:p.id}).catch(()=>{});area.replaceChildren()};
    $('#applyRestore').onclick=async()=>{const button=$('#applyRestore');if(!await confirmAction(`Replace your current manager settings with ${p.workspace}? Current recordings and stream forwarding will stop. Restored cameras will be paused, and schedules, public sharing and cleanup will be off. Saved video files will remain.`))return;button.disabled=true;try{state=await request('backup/apply',{id:p.id});render();toast('Settings restored. Review and resume your cameras.')}catch(error){$('#applyRestoreResult').textContent=error.message}finally{if(button.isConnected)button.disabled=false}};
  }
  $('#backupRestoreForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),result=$('#backupRestoreResult');b.disabled=true;$('#backupPreview').replaceChildren();try{const file=f.elements.backupFile.files[0];if(!file||file.size>2097152)throw Error('Choose a manager backup file smaller than 2 MB.');let backup;try{backup=JSON.parse(await file.text())}catch{throw Error('This file is not a valid JSON backup.')}const preview=await request('backup/preview',{backup,passphrase:f.elements.passphrase.value});f.elements.passphrase.value='';result.textContent='Backup checked. Nothing has been changed.';showPreview(preview)}catch(error){result.textContent=error.message}finally{b.disabled=false}};
  try{const r=await fetch('/api/backup/status',{cache:'no-store'});if(!r.ok)throw Error('Apply the backup and restore update to use these controls.');const {previous}=await r.json();if(!panel.isConnected)return;if(previous){$('#previousSetup').innerHTML=`<p>Previous local setup: ${esc(previous.workspace)} · ${previous.cameras} camera(s) · ${esc(new Date(previous.createdAt).toLocaleString())}</p><button type="button" class="secondary" id="previewPrevious">Preview previous setup</button>`;$('#previewPrevious').onclick=async()=>{try{showPreview(await request('backup/previous-preview'))}catch(error){toast(error.message)}}}}catch(error){$('#backupRestoreResult').textContent=error.message}
}
function storageValues(form){return {enabled:form.elements.enabled.checked,keepDays:Number(form.elements.keepDays.value),maxGB:Number(form.elements.maxGB.value),minFreeGB:Number(form.elements.minFreeGB.value)}}
function space(bytes){return bytes===null?'Unavailable':(bytes/1073741824).toFixed(2)+' GB'}
async function loadAutomation(){
  const library=$('#recordingList');if(!library)return;$('#automationPanel')?.remove();
  const panel=document.createElement('div');panel.id='automationPanel';panel.className='automation-stack';library.before(panel);panel.textContent='Loading recording schedules and storage…';
  try{const r=await fetch('/api/automation',{cache:'no-store'});if(!r.ok)throw Error('Apply the schedules and storage update to use these controls.');const a=await r.json();if(!panel.isConnected)return;const s=a.storage.settings;
    panel.innerHTML=`<section class="panel"><h2>Recording schedules</h2><p class="hint">Times use the camera computer’s clock: <strong>${esc(a.timezone)}</strong>. The manager, server and camera must be running. Schedules do not wake a sleeping computer. End times earlier than start times finish the following day.</p><p class="hint">Manual recordings continue until you stop them. Stop recording skips the rest of the current scheduled session; the next scheduled session can start normally.</p>${a.cameras.map(c=>{const v=c.schedule;return `<form class="schedule-form" data-schedule="${esc(c.id)}"><h3>${esc(c.name)}</h3><label class="inline-check"><input type="checkbox" name="enabled" ${v.enabled?'checked':''}> Enable scheduled recording</label><fieldset class="schedule-days"><legend>Start days</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${v.days.includes(i)?'checked':''}> ${d}</label>`).join('')}</fieldset><div class="form-grid"><label>Start time<input type="time" name="start" required value="${v.start}"></label><label>End time<input type="time" name="end" required value="${v.end}"></label></div><p class="hint">${c.paused?'Camera paused. Resume it to record.':c.record?(c.manualRecord?'Manual recording is active.':'Scheduled recording is active.'):'Not recording.'}</p><button class="primary">Save schedule</button><p role="status" class="hint form-result"></p></form>`}).join('')||'<p class="hint">Add a camera to set its recording schedule.</p>'}</section><section class="panel"><h2>Recording storage</h2><p class="hint"><strong>${space(a.storage.usedBytes)}</strong> used by recordings · <strong>${space(a.storage.freeBytes)}</strong> free on the drive</p>${a.storage.blocked?'<p class="error-text" role="alert">Recording is paused by your storage limits. Live viewing continues.</p>':''}${a.storage.error?`<p class="error-text" role="alert">${esc(a.storage.error)}</p>`:''}<form id="storageForm" class="settings"><label>Automatically delete oldest completed recordings<input name="enabled" type="checkbox" ${s.enabled?'checked':''}></label><label>Keep recordings for this many days<input name="keepDays" type="number" min="0" max="1000000" step="1" required value="${s.keepDays}"></label><label>Maximum recording storage (GB)<input name="maxGB" type="number" min="0" max="1000000" step="0.1" required value="${s.maxGB}"></label><label>Keep this much drive space free (GB)<input name="minFreeGB" type="number" min="0" max="1000000" step="0.1" required value="${s.minFreeGB}"></label><p class="hint">Use 0 to leave an individual limit off. Saving with automatic cleanup enabled starts permanent deletion of eligible recordings. Files being recorded and files updated in the last two minutes are protected. Cleanup runs about once a minute; storage protection is checked about every five seconds. If the limits cannot be met, recording pauses and resumes when space is available.</p><div class="page-actions"><button class="secondary" type="button" id="previewCleanup">Preview these limits</button><button class="primary">Save storage limits</button><button class="secondary" type="button" id="cleanupNow" ${s.enabled?'':'disabled'}>Run cleanup now</button></div><p role="status" id="storageResult" class="hint">${a.storage.lastResult?`Last cleanup: ${a.storage.lastResult.removed} files removed, ${space(a.storage.lastResult.freedBytes)} reclaimed.`:'Automatic cleanup is off until you enable it.'}</p></form></section>`;
    $('#previewCleanup').onclick=async()=>{try{const p=await request('automation/preview',storageValues($('#storageForm')));$('#storageResult').textContent=`Preview only: ${p.count} completed file(s) eligible, about ${space(p.freedBytes)} would be removed. Nothing was deleted.`}catch(e){$('#storageResult').textContent=e.message}};
    $('#cleanupNow').onclick=async()=>{try{const r=await fetch('/api/automation',{cache:'no-store'}),latest=await r.json(),p=latest.storage.preview;if(!p.count){$('#storageResult').textContent='No completed recordings currently need cleanup.';return}if(!await confirmAction(`Permanently delete approximately ${p.count} eligible recording file(s), reclaiming ${space(p.freedBytes)}, using your saved limits?`))return;await request('automation/cleanup');loadAutomation();loadRecordings()}catch(e){toast(e.message)}};
  }catch(e){panel.textContent=e.message}
}
document.addEventListener('submit',async e=>{
  const f=e.target;if(!f.dataset.schedule&&f.id!=='storageForm')return;e.preventDefault();const button=f.querySelector('button[type="submit"],button.primary'),result=f.querySelector('.form-result')||$('#storageResult');button.disabled=true;
  try{if(f.dataset.schedule){await request('automation/schedule',{id:f.dataset.schedule,schedule:{enabled:f.elements.enabled.checked,days:Array.from(f.querySelectorAll('[name="day"]:checked'),el=>Number(el.value)),start:f.elements.start.value,end:f.elements.end.value}});result.textContent='Schedule saved. Times follow the camera computer’s clock.'}else{const a=await request('automation/storage',storageValues(f));result.textContent=`Storage limits saved. ${a.storage.lastResult?.removed||0} file(s) removed in the latest cleanup.`;$('#cleanupNow').disabled=!a.storage.settings.enabled}toast('Recording preferences saved')}catch(err){result.textContent=err.message}finally{button.disabled=false}
});
async function loadSharing(){
  const stack=$('.settings-stack');if(!stack)return;
  const panel=document.createElement('section');panel.className='panel';panel.id='websiteSharing';stack.insertBefore(panel,stack.children[1]);panel.textContent='Loading website sharing…';
  try{const r=await fetch('/api/sharing',{cache:'no-store'});if(!r.ok)throw Error('Website sharing needs the updated manager.');const s=await r.json();if(!panel.isConnected)return;
    panel.innerHTML=`<h2 class="small-heading">Public website viewing</h2><p class="hint">Visitors can watch the cameras you select here. Your camera passwords, recordings and manager controls are kept separate. Video only loads after a visitor presses Watch live.</p><form id="sharingForm" class="settings"><label>Allow public viewing<input type="checkbox" name="enabled" ${s.enabled?'checked':''}></label><fieldset><legend>Cameras to show publicly</legend>${s.cameras.map(c=>`<label>${esc(c.name)}<input type="checkbox" name="camera" value="${esc(c.id)}" ${c.publicViewing?'checked':''}></label>`).join('')||'<p>Add a camera first.</p>'}</fieldset><label>Default Watch page quality<select name="defaultQuality"><option value="standard" ${s.defaultQuality!=='saver'?'selected':''}>Standard · 360p</option><option value="saver" ${s.defaultQuality==='saver'?'selected':''}>Data Saver · 180p</option></select></label><p class="hint">Visitors can change quality on the Watch page. Their saved choice takes priority. This does not change camera feeds or recordings.</p><label>Public viewer address<input name="baseUrl" type="url" placeholder="https://live.yourdomain.com" value="${esc(s.baseUrl)}"></label><p class="hint">This address needs a separate HTTPS video connection to this computer. Saving an address does not create that connection.</p><button class="primary">Save website sharing</button><p id="sharingMessage" role="status"></p></form><p><a class="download-link" href="${esc(s.localUrl)}" target="_blank" rel="noopener">Preview public viewer on this computer ↗</a></p>${s.baseUrl?`<p>Website link: <a class="download-link" href="${esc(s.baseUrl)}/watch/" target="_blank" rel="noopener">${esc(s.baseUrl)}/watch/</a></p>`:''}<p class="hint">Viewer connection: ${esc(s.localUrl)} · Publish this viewer service only. ${esc(s.error)}</p>`;
    if(s.websiteQuality){const note=document.createElement('p');note.className='hint';note.textContent='Website viewers receive a lighter, mobile-friendly feed. Your local previews and recordings keep their original quality. '+s.websiteQuality;panel.querySelector('h2').after(note)}
  }catch(e){panel.textContent=e.message}
}
document.addEventListener('submit',async e=>{if(e.target.id!=='sharingForm')return;e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;try{await request('sharing',{enabled:f.elements.enabled.checked,defaultQuality:f.elements.defaultQuality.value,baseUrl:f.elements.baseUrl.value.trim(),cameras:Array.from(f.querySelectorAll('[name="camera"]:checked'),el=>el.value)});$('#sharingMessage').textContent='Sharing settings saved. The public address still needs a working video connection.';toast('Website sharing settings saved')}catch(err){$('#sharingMessage').textContent=err.message}finally{button.disabled=false}});
function navigate(n){active=names.includes(n)?n:'Dashboard';move();render();history.replaceState(null,'','#'+active.toLowerCase())}
let mutationVersion=0;
async function request(endpoint,body={},method='POST'){mutationVersion++;try{const r=await fetch('/api/'+endpoint,{method,headers:{'Content-Type':'application/json','X-Manager-Token':token},body:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw new Error(v.error||'Request failed.');return v}finally{mutationVersion++}}
const signature=s=>JSON.stringify([s.server.running,s.server.error,s.server.sampleRunning,s.workspace,s.cameras.map(c=>[c.id,c.name,c.path,c.record,c.enabled,c.status]),s.activity[0]]);
async function refresh(force=false){if(!local||polling)return;polling=true;const version=mutationVersion;try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw new Error();const next=await r.json();if(version!==mutationVersion)return;const now=performance.now(),total=next.paths.reduce((v,p)=>({incoming:v.incoming+p.inboundBytes,outgoing:v.outgoing+p.outboundBytes}),{incoming:0,outgoing:0});if(lastTraffic){let sec=(now-lastTraffic.time)/1000;points.push({incoming:Math.max(0,total.incoming-lastTraffic.incoming)*8/sec/1e6,outgoing:Math.max(0,total.outgoing-lastTraffic.outgoing)*8/sec/1e6});points=points.slice(-40)}lastTraffic={...total,time:now};const changed=signature(state)!==signature(next);state=next;if(next.managerRunning===false){if(!managerStopped)showManagerStopped();return}if(managerStopped){managerStopped=false;lastTraffic=null;points=[];render();return}header();syncServerControls();document.querySelectorAll('[data-viewers]').forEach(el=>{el.textContent=(state.cameras.find(c=>c.id===el.dataset.viewers)?.publicViewers||0)+' watching on website'});if($('#websiteViewerTotal'))$('#websiteViewerTotal').textContent=state.viewerCount||0;if((changed||force)&&!document.querySelector('dialog[open]')&&(force||(!$('#settingsForm')&&!document.activeElement?.closest('#automationPanel,#forwardingPanel'))))render();if($('#bandwidth'))$('#bandwidth').textContent=(points.at(-1)?.incoming||0).toFixed(2);if($('#uptime'))$('#uptime').textContent=state.server.running?uptime():'—';plot()}catch{$('#serverBadge').textContent='Manager unavailable';$('#footerStatus').textContent='Reopen Start Manager.vbs to reconnect.'}finally{polling=false}}
function play(video,url){
  video.muted=true;video.defaultMuted=true;
  const begin=()=>video.play().catch(()=>{});
  video.addEventListener('canplay',begin,{once:true});
  if(window.Hls?.isSupported()){
    const h=new Hls({liveSyncDurationCount:2});players.push(h);h.attachMedia(video);h.loadSource(url);
    h.on(Hls.Events.MANIFEST_PARSED,begin);
    h.on(Hls.Events.ERROR,(_,d)=>{if(d.fatal){if(d.type===Hls.ErrorTypes.MEDIA_ERROR){h.recoverMediaError();return}if(!video.parentElement.querySelector('.video-error'))video.insertAdjacentHTML('afterend','<p class="video-error">Video unavailable. Check the camera connection, then refresh.</p>')}});
  }else if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=url;begin()}
  else video.insertAdjacentHTML('afterend','<p class="video-error">Use a current Edge or Chrome browser for this stream.</p>');
}
function attachLive(){document.querySelectorAll('video[data-live]').forEach(v=>play(v,`/hls/${encodeURIComponent(v.dataset.live)}/index.m3u8`))}
async function loadRecordings(){if(!local)return;try{const r=await fetch('/api/recordings',{cache:'no-store'}),v=await r.json();if(!r.ok)throw new Error(v.error);recordFiles=v.items;if(!$('#recordingList'))return;$('#recordingList').innerHTML=recordFiles.length?`<div class="table-wrap"><table><thead><tr><th>CAMERA / CREATED</th><th>SIZE</th><th>ACTIONS</th></tr></thead><tbody>${recordFiles.map(f=>`<tr><td>${esc(f.camera)}<br><span class="hint">${new Date(f.modified).toLocaleString()}</span></td><td>${(f.size/1048576).toFixed(1)} MB</td><td>${f.finalized?`<button data-file="${f.id}">Play</button> <a class="download-link" href="/api/recordings/file/${f.id}?download=1" download>Download</a>`:'Recording… stop to finalize'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No recordings yet.<br><br>Start a sample stream or add a camera, then select Record.</div>'}catch(e){toast(e.message)}}
function syncCameraSetup(){const f=$('#cameraForm'),custom=f.elements.sourceType.value==='custom',auth=!custom||f.elements.cameraAuth.value==='yes',c=state.cameras.find(c=>c.id===f.elements.id.value);$('#tapoStreamField').hidden=custom;$('#customStreamField').hidden=!custom;$('#cameraAuthField').hidden=!custom;$('#cameraCredentials').hidden=!auth;$('#tapoHelp').hidden=custom;f.elements.host.required=local;f.elements.username.required=local&&auth;f.elements.password.required=local&&auth&&(!c||c.authRequired===false||!c.hasPassword);f.elements.password.placeholder=c?.hasPassword?'Leave blank to keep saved password':''}
function openCamera(id){const f=$('#cameraForm');f.reset();f.elements.id.value=id||'';const c=state.cameras.find(c=>c.id===id);$('#cameraTitle').textContent=c?'Edit camera':'Add a camera';$('#cameraIntro').textContent=local?'Connect a Tapo camera or another RTSP camera.':'Add a placeholder to explore the layout. Camera connections are available in the local Windows app.';$('#connectionFields').hidden=!local;if(c){['name','path','host','port','username'].forEach(k=>{f.elements[k].value=c[k]||''});f.elements.sourceType.value=c.sourceType||'tapo';f.elements.cameraAuth.value=c.authRequired===false?'no':'yes';if(c.sourceType==='custom')f.elements.customStream.value=c.stream;else f.elements.stream.value=c.stream}syncCameraSetup();$('#cameraError').textContent='';$('#saveCamera').textContent=local?'Save camera':'Add preview camera';$('#addDialog').showModal()}
$('#cameraForm').addEventListener('change',e=>{if(['sourceType','cameraAuth'].includes(e.target.name))syncCameraSetup()});
async function action(a){if(!local){if(a==='recordings')toast('Use the local Windows app for recordings.');else $('#setupDialog').showModal();return}if(a==='refresh')return refresh(true);if(a==='recordings')return loadRecordings();if(['shutdown','server/stop'].includes(a)&&!await confirmAction(a==='shutdown'?'Stop MediaMTX and quit the manager?':'Stop the server, previews and current recordings?'))return;const result=await request(a);if(a==='shutdown'){state={...state,managerRunning:false,server:{...state.server,running:false,sampleRunning:false}};showManagerStopped();return}state=result;if(a==='manager/start'){managerStopped=false;token=result.token||token;lastTraffic=null;points=[]}header();if(active==='Settings'&&a!=='manager/start')syncServerControls();else render()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.page)return navigate(b.dataset.page);if(b.hasAttribute('data-close'))return b.closest('dialog').close();if(b.hasAttribute('data-setup'))return $('#setupDialog').showModal();if(b.hasAttribute('data-add'))return openCamera();if(b.dataset.edit)return openCamera(b.dataset.edit);if(b.dataset.action){b.disabled=true;try{await action(b.dataset.action)}finally{b.disabled=false;if(local)syncServerControls()}return}if(b.dataset.view){const c=state.cameras.find(c=>c.id===b.dataset.view);$('#viewerTitle').textContent=c.name;$('#viewerBody').innerHTML='<video autoplay muted controls playsinline aria-label="Expanded live video"></video>';$('#viewer').showModal();play($('#viewer video'),`/hls/${c.path}/index.m3u8`);return}if(b.dataset.file){$('#viewerTitle').textContent='Recorded video';$('#viewerBody').innerHTML=`<video src="/api/recordings/file/${b.dataset.file}" controls autoplay playsinline aria-label="Recorded video playback"></video>`;$('#viewer').showModal();return}const id=b.dataset.record||b.dataset.enabled||b.dataset.remove;if(id&&local){const c=state.cameras.find(c=>c.id===id);if(b.dataset.remove){if(!await confirmAction(`Remove ${c.name}? Saved recordings will remain. Its forwarding destinations will also be removed.`))return;await updateCamera('cameras/'+id,{},'DELETE')}else if(b.dataset.record)await updateCamera(`cameras/${id}/record`,{record:!c.record});else await updateCamera(`cameras/${id}/enabled`,{enabled:isPaused(c)});await refresh(true);toast('Camera updated')}}catch(err){toast(err.message)}});
