document.addEventListener('submit',async e=>{if(e.target.id!=='settingsForm')return;e.preventDefault();const f=e.target;try{if(local)state=await request('workspace',{workspace:f.elements.workspace.value});else{state.workspace=f.elements.workspace.value;localStorage.setItem('mtx-workspace',state.workspace)}motion=f.elements.motion.checked;localStorage.setItem('mtx-motion',motion);header();toast('Preferences saved')}catch(err){toast(err.message)}});
