async function boot(){if(['localhost','127.0.0.1'].includes(location.hostname))try{const r=await fetch('/api/bootstrap',{cache:'no-store'});if(r.ok&&r.headers.get('content-type')?.includes('application/json')){state=await r.json();token=state.token;local=true}}catch{}if(!state){state=demo;state.workspace=localStorage.getItem('mtx-workspace')||demo.workspace}managerStopped=state.managerRunning===false;navigate(names.find(n=>n.toLowerCase()===location.hash.slice(1))||'Dashboard');if(local&&state.launcherAvailable){pageHeartbeat();setInterval(pageHeartbeat,10000)}if(local)setInterval(()=>refresh(),3000);setInterval(updateRecordingTimers,1000)}boot();
function faqPage(){const topics=[
 ['Cameras and connections',[
 ['Why does my camera say “Waiting for video”?','Check that the camera is powered on, connected to your network, and has the correct IP address. For Tapo, create a Camera Account in the Tapo app’s advanced camera settings. That account is separate from your normal Tapo sign-in. Try the main or low-bandwidth stream and choose H.264 where your camera offers that setting.'],
 ['Do I need to forward port 554 in my router?','Local camera viewing does not require router port forwarding. The manager connects to your camera over your local network. Public website viewing uses its separate HTTPS viewer connection; do not expose the manager controls or camera password to website visitors.'],
 ['Can I use cameras from other brands?','Choose Other RTSP camera when adding a camera, then enter the manufacturer’s RTSP path and login details. The camera must offer RTSP. The connection flow has been tested with local streams; individual camera models can behave differently. Automatic camera discovery is not included.']]],
 ['Website viewing and quality',[
 ['Where do visitors change video quality?','Each camera on the Watch page has a Quality menu. Standard is 640 × 360 at 15 frames per second. Data Saver is 320 × 180 at 10 frames per second and uses less data. Switching quality reconnects that player briefly. The visitor’s choice is saved in their browser and does not change your camera feed or recordings.'],
 ['Can I choose the starting quality?','In Settings → Public website viewing, choose Default Watch page quality and save. This applies to visitors who have not saved their own choice. Visitors can still select a different quality.'],
 ['Why does the live video buffer?','Your visitor’s connection, the camera’s Wi-Fi, your studio’s upload speed and the number of viewers can all affect playback. Try Data Saver. A few seconds of delay behind the camera is normal for this website feed.'],
 ['What does “watching on website” mean?','It estimates active viewing sessions, not verified individual people. One page watching two cameras counts once overall and once for each camera. Separate tabs or devices can count separately. Pausing or stopping removes a session; a disconnected or stalled session expires within 45 seconds after its last update. Local manager previews and stream-forwarding destinations are not included. No IP addresses or viewing history are stored for this count.'],
 ['Do viewers see my camera passwords or recordings?','The public viewer only receives the cameras you explicitly share. It has no route to camera passwords, saved recordings or manager controls. Turn public viewing off in Settings to remove access.']]],
 ['Recording, backups and the app',[
 ['Does changing website quality affect recordings?','No. Website quality uses separate resized feeds. Recordings use the camera’s configured source quality. The recording timer shows how long the current recording has run. Stop recording before playing or downloading the final file.'],
 ['How do I avoid filling my disk?','Under Recordings, configure storage cleanup and review its preview before enabling it. You can use age, storage-size and free-space limits. Recent or active recording files are protected. Cleanup is off until you enable it.'],
 ['Does a settings backup include recorded videos?','No. The encrypted backup stores your setup and can optionally include camera passwords and stream keys. Copy video files separately. Keep the backup passphrase safe; it cannot be recovered. Restored cameras start paused and automation starts disabled for review.'],
 ['What happens when I close the tab or desktop window?','The local manager keeps running, including active recordings. Use Settings → Quit manager to stop it. Start manager then remains available on that page so you can restart in the same window. Desktop shortcuts return to the app without searching through folders.'],
 ['Are all features tested with every camera and streaming service?','No. Tapo viewing and recording have been confirmed by the owner. Local tests cover additional RTSP sources and RTMP forwarding. Other physical camera models, secure RTMPS forwarding and outside streaming-service integrations still need their own verification.']]]
 ];return '<div class="faq-stack">'+topics.map(([title,questions])=>'<section class="panel"><h2>'+title+'</h2>'+questions.map(([q,a])=>'<details class="faq-item"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</section>').join('')+'</div>'}
